"""Verify bytes and collection status without executing any downloaded challenge."""
import hashlib,json,pathlib,re,zipfile
import collect_pwn as c
ROOT=c.ROOT
FOLDERS={s[2] for s in c.SPECS}|{'Undutmaning_2026','0xFUN_CTF_2026','Thryve_CTF_2026'}

def main():
    records=[];failures=[];zip_results=[];file_count=0;byte_count=0
    for folder in sorted(FOLDERS):
        for mf in (ROOT/'pwn'/folder).glob('*/metadata.json'):
            m=json.loads(mf.read_text(encoding='utf8'));base=mf.parent
            m['collector']='pwn_agent';m['retrieved_date']='2026-11-06'
            # Generated repository-layout README files are not narrative writeups.
            if 'prose_files' in m:
                prose=[]
                for rel in m['prose_files']:
                    text=(base/rel).read_text(encoding='utf8',errors='replace')
                    if len(text.strip())<60 or 'This README was autogenerated by `mkchal.py`' in text:continue
                    if rel.endswith('/images/README.md'):continue
                    prose.append(rel)
                m['prose_files']=prose
                scripts=[a for a in m['artifacts'] if a['kind']=='writeups' and pathlib.Path(a['path']).suffix.lower() in ('.py','.c','.rb','.sh','.zag','.s') and not a['path'].endswith('solver-template.py')]
                if m.get('has_verified_solution'):
                    m['writeup_status']='已下载正文及解题脚本' if prose and scripts else '已下载正文' if prose else '已下载官方解题脚本（独立文字writeup未提供）'
                    if folder=='LACTF_2026' and base.name=='tic-tac-no':
                        m['writeup_status']='已下载官方解题输入（solve.txt，非长篇正文）'
            m.setdefault('attachment_complete',m.get('has_verified_solution',False) and not any(e.get('kind')=='attachments' for e in m.get('download_errors',[])))
            for a in m.get('artifacts',[]):
                p=base/a['path'];file_count+=1;byte_count+=a['bytes']
                if not p.exists():failures.append({'file':str(p),'reason':'missing'});continue
                actual=hashlib.sha256(p.read_bytes()).hexdigest()
                if p.stat().st_size!=a['bytes'] or actual!=a['sha256']:failures.append({'file':str(p),'reason':'size or SHA256 mismatch'})
                if p.suffix.lower()=='.zip' and a.get('git_mode')!='120000':
                    try:
                        with zipfile.ZipFile(p) as z:
                            # CRC-test the archive without writing or running its members.
                            bad=z.testzip()
                            if bad:failures.append({'file':str(p),'reason':'ZIP CRC mismatch: '+bad})
                            zip_results.append({'file':str(p.relative_to(ROOT)),'members':len(z.infolist()),'crc_ok':not bad})
                    except NotImplementedError:
                        zip_results.append({'file':str(p.relative_to(ROOT)),'crc_ok':None,'note':'compression method unsupported; file SHA256 verified'})
                    except Exception as ex:failures.append({'file':str(p),'reason':'ZIP check: '+str(ex)})
            mf.write_text(json.dumps(m,ensure_ascii=False,indent=2),encoding='utf8')
            # Rebuild local overview with unambiguous statuses.
            note='\n\n此题尚未取得有效writeup，列为待补，不计入已收录有效题。' if not m.get('has_verified_solution') else ''
            (base/'README.md').write_text(f'# {m["title"]}\n\n比赛：{m["event_title"]}（{m["event_id"]}）\n\n类别：{m["category"]}\n\n解答状态：{m["writeup_status"]}\n\n附件状态：{m["attachment_status"]}'+note+'\n\n来源：\n\n'+'\n'.join('- '+u for u in m['source_urls'])+'\n\n- `attachments/` 保存题目包、源码或环境文件。\n- `writeups/` 保存解答正文/官方solver，具体形式见上面状态。\n- `metadata.json` 记录逐文件来源、字节数、SHA-256和缺失项。\n\n'+'\n'.join(m['notes'])+'\n',encoding='utf8')
            records.append({'event_id':m['event_id'],'event_title':m['event_title'],'title':m['title'],'path':base.relative_to(ROOT).as_posix(),'files':len(m['artifacts']),'bytes':sum(a['bytes'] for a in m['artifacts']),'errors':m.get('download_errors',[]),'has_verified_solution':m.get('has_verified_solution',False),'attachment_complete':m['attachment_complete'],'writeup_status':m['writeup_status'],'attachment_status':m['attachment_status']})
    log=ROOT/'sources/pwn_search.json';old=json.loads(log.read_text(encoding='utf8')) if log.exists() else {}
    old.update(records=records,search_queries=list(dict.fromkeys(old.get('search_queries',[])+c.SEARCH_QUERIES+['site:github.com "SUCTF2026" pwn','site:github.com "srdnlen" "2026" "challenges"','BSidesSF 2026 github challenges solution inheritance readme','Undutmaning 2026 GIF Splitter Flytväst writeup','"SU_fullchian" writeup','"SUCTF 2026" "fullchain" writeup','"0xfun" "phantom" "initramfs" github','"Thryve" "Abyss Oracle" "download"'])),notes=['官方或参赛者solution/solver算解答，但与文字writeup分别标记。','检查发现并排除空模板：Undutmaning2题和SU_fullchian；BSidesSF旧空模板已补入官方solution。','未执行任何下载文件或solver。'])
    log.write_text(json.dumps(old,ensure_ascii=False,indent=2),encoding='utf8')
    report={'records':len(records),'valid_challenges':sum(r['has_verified_solution'] for r in records),'valid_events':len({r['event_id'] for r in records if r['has_verified_solution']}),'complete_attachments':sum(r['has_verified_solution'] and r['attachment_complete'] for r in records),'files_verified':file_count,'bytes_verified':byte_count,'failures':failures,'zip_checks':zip_results,'pending':[r['path'] for r in records if not r['has_verified_solution']]}
    (ROOT/'sources/pwn_validation.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
    print(json.dumps({k:v for k,v in report.items() if k!='zip_checks'},ensure_ascii=False))

if __name__=='__main__':main()
